	if _, e = again.UploadAsset(ctx, next.ID, []byte("review")); e != nil {
		t.Fatal(e)
	}
	if _, e = again.LinkAsset(ctx, next.ID, nil); e != nil {
		t.Fatal(e)
	}
	nativeFailed(t, again, a)
}"}

